/**
 * waste.ts — the waste and land ledger.
 *
 * Built 24 October 2026. This replaces the single largest known error in the
 * model: waste was a function of LICENCE AREA, independent of how much ore was
 * removed and with no lifetime attached. A 0.5 km2 mine produced 1.5 Mt of
 * waste whether it ran at 0.5 or 5 Mt/yr.
 *
 * The causal arrow was backwards. Every operation in the record reports waste as
 * a RATIO TO ORE - the strip ratio. Waste is generated by removing ore; area is
 * a consequence of waste tonnage and dump geometry, not a cause. So this module
 * computes tonnage first and derives footprint from it.
 *
 * Two streams, not one. The old model had no tailings at all, which for a
 * concentrator is the larger of the two by mass.
 */

import {
  BACKFILL_TAILINGS_UPTAKE,
  CONCENTRATE_GRADE_LI2O,
  FEED_GRADE_LI2O,
  ORE_T_PER_KM2,
  RECOVERY_FRACTION,
  STRIP_RATIO_UNDERGROUND,
  TAILINGS_AREA_HA_PER_MT,
  TAILINGS_AREA_INTERCEPT_HA,
  WASTE_DUMP_AREA_HA_PER_MT,
  WASTE_DUMP_AREA_INTERCEPT_HA,
} from './params.ts';
import { mineLifeYr } from './hydrology.ts';

export type WasteLedger = {
  inputs: { mineSizeKm2: number; capacityTPerYr: number; backfillFraction: number };

  /** Tonnes, over the life of the mine unless stated. */
  tonnage: {
    oreMinedT: number;
    /** Development and barren rock raised to surface. */
    wasteRockT: number;
    /** Plant reject. The larger stream for a concentrator. */
    tailingsT: number;
    /** Tailings placed underground as cemented paste rather than impounded. */
    tailingsBackfilledT: number;
    /** Tailings that must be impounded on the surface. */
    tailingsToSurfaceT: number;
    totalToSurfaceT: number;
    /** Annual rates, for comparison with the water ledger's per-year figures. */
    wasteRockTPerYr: number;
    tailingsToSurfaceTPerYr: number;
  };

  /** The mass-yield identity, exposed so it can be checked rather than trusted. */
  massYield: {
    feedGradeLi2O: number;
    recoveryFraction: number;
    concentrateGradeLi2O: number;
    /** y = feed x recovery / concentrate. Tailings are (1 - y) x ore. */
    yieldFraction: number;
    concentrateT: number;
  };

  /** Hectares. Derived from tonnage, which is the correction. */
  footprint: {
    wasteDumpHa: number;
    tailingsImpoundmentHa: number;
    totalDisturbedHa: number;
    /** The licence area the community voted for, for comparison. */
    licenceAreaHa: number;
    /** True when the disturbed ground exceeds the area the community allowed. */
    exceedsLicenceArea: boolean;
  };

  timing: { mineLifeYr: number };
};

export function computeWasteLedger(input: {
  mineSizeKm2: number;
  capacityTPerYr: number;
  /** Share of tailings placed underground as paste backfill, 0-1. */
  backfillFraction?: number;
}): WasteLedger {
  const { mineSizeKm2, capacityTPerYr } = input;
  const beta = clamp01(input.backfillFraction ?? 0);

  const reserveT = mineSizeKm2 * ORE_T_PER_KM2;
  const lifeYr = mineLifeYr(reserveT, capacityTPerYr);
  const oreMinedT = reserveT;

  const wasteRockT = oreMinedT * STRIP_RATIO_UNDERGROUND;

  // Mass yield identity: y = feed grade x recovery / concentrate grade.
  const yieldFraction = (FEED_GRADE_LI2O * RECOVERY_FRACTION) / CONCENTRATE_GRADE_LI2O;
  const concentrateT = oreMinedT * yieldFraction;
  const tailingsT = oreMinedT * (1 - yieldFraction);

  // Paste backfill takes tailings underground. It cannot take all of them:
  // binder and void geometry cap the uptake well below unity.
  const tailingsBackfilledT = tailingsT * beta * BACKFILL_TAILINGS_UPTAKE;
  const tailingsToSurfaceT = tailingsT - tailingsBackfilledT;

  const wasteMt = wasteRockT / 1e6;
  const tailsMt = tailingsToSurfaceT / 1e6;
  const wasteDumpHa = wasteMt > 0 ? WASTE_DUMP_AREA_HA_PER_MT * wasteMt + WASTE_DUMP_AREA_INTERCEPT_HA : 0;
  const tailingsImpoundmentHa = tailsMt > 0 ? TAILINGS_AREA_HA_PER_MT * tailsMt + TAILINGS_AREA_INTERCEPT_HA : 0;
  const totalDisturbedHa = wasteDumpHa + tailingsImpoundmentHa;
  const licenceAreaHa = mineSizeKm2 * 100;

  return {
    inputs: { mineSizeKm2, capacityTPerYr, backfillFraction: beta },
    tonnage: {
      oreMinedT,
      wasteRockT,
      tailingsT,
      tailingsBackfilledT,
      tailingsToSurfaceT,
      totalToSurfaceT: wasteRockT + tailingsToSurfaceT,
      wasteRockTPerYr: lifeYr > 0 ? wasteRockT / lifeYr : 0,
      tailingsToSurfaceTPerYr: lifeYr > 0 ? tailingsToSurfaceT / lifeYr : 0,
    },
    massYield: {
      feedGradeLi2O: FEED_GRADE_LI2O,
      recoveryFraction: RECOVERY_FRACTION,
      concentrateGradeLi2O: CONCENTRATE_GRADE_LI2O,
      yieldFraction,
      concentrateT,
    },
    footprint: {
      wasteDumpHa,
      tailingsImpoundmentHa,
      totalDisturbedHa,
      licenceAreaHa,
      exceedsLicenceArea: totalDisturbedHa > licenceAreaHa,
    },
    timing: { mineLifeYr: lifeYr },
  };
}

function clamp01(x: number): number {
  if (!Number.isFinite(x)) return 0;
  return Math.max(0, Math.min(1, x));
}
